package com.mavric.health.clinical.application;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.clinical.domain.Requests.*;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerClinicalStoreTest.Fixture;
import tools.jackson.databind.ObjectMapper;
import static com.mavric.health.persistence.sqlserver.SqlServerClinicalStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real service/store with offline executor, modeled TX and synthetic validation shapes only. */
class ClinicalServiceSqlServerTest {
 final Fixture f=new Fixture();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final ClinicalService service=new ClinicalService(f.store,access,f.mapper);
 ClinicalServiceSqlServerTest(){actor("PRO");when(access.userId()).thenReturn(ACTOR);}
 void actor(String role){f.actor(role);doReturn(f.actor).when(access).actor();TraceContext.REQUEST.set(f.request);}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 Entry evaluation(){return new Entry("EVALUATION",Map.of("profileCode","H_FAMILY","values",Map.of("number",3,"option","A")));}
 Entry annotation(String family){return new Entry("ANNOTATION",Map.of("component",family,"structure","Synthetic","condition","Synthetic"));}
 Map<String,Object> add(Entry input){return service.entry(ENCOUNTER,input);}
 void rejected(Entry input,int status){int before=f.calls.size();var e=assertThrows(ApiException.class,()->add(input));assertEquals(status,e.status);assertEquals(before+1,f.calls.size());assertEquals(SqlServerProcedure.ENCOUNTER_GET,f.calls.getLast());assertEquals("rollback",f.manager.events.getLast());}
 @Test void getReadRolesTenantWideOneAuditedSpNoBranchOrWriteGate(){for(String role:List.of("PRO","ASI","AUD")){actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of()));f.current.put("branchId",OTHER);assertEquals(14,service.get(ENCOUNTER).size());}verify(access,times(3)).roles("PRO","ASI","AUD");verify(access,never()).branch(anyString());verify(access,never()).write(anyString(),any(String[].class));assertEquals(Collections.nCopies(3,SqlServerProcedure.ENCOUNTER_GET),f.calls);verifyNoInteractions(sql);}
 @Test void startOnlyOneSpWithSameMapperAndBranchBeforeMutation(){var input=new Start(PATIENT,BRANCH,"H_FAMILY");var row=service.start(input);assertEquals(14,row.size());assertEquals(List.of(SqlServerProcedure.ENCOUNTER_START),f.calls);var order=inOrder(access,f.executor);order.verify(access).write("CORE","PRO");order.verify(access).branch(BRANCH);order.verify(f.executor).execute(eq(SqlServerProcedure.ENCOUNTER_START),any(),any(Object[].class));assertEquals(f.mapper.writeValueAsString(input),f.args.getFirst().get(1));assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals(1,Collections.frequency(f.manager.events,"commit"));verifyNoInteractions(sql);}
 @Test void notePriorGetThenBranchThenOneNoteWithoutTrailingGet(){var row=service.note(ENCOUNTER,new Note(1,"Synthetic summary"),true);assertEquals("FINALIZED",row.get("status"));assertEquals(2,row.get("revision"));assertEquals(List.of(SqlServerProcedure.ENCOUNTER_GET,SqlServerProcedure.ENCOUNTER_NOTE),f.calls);var order=inOrder(access,f.executor);order.verify(access).write("CORE","PRO");order.verify(access).roles("PRO","ASI","AUD");order.verify(f.executor).execute(eq(SqlServerProcedure.ENCOUNTER_GET),any(),eq(ENCOUNTER));order.verify(access).branch(BRANCH);order.verify(f.executor).execute(eq(SqlServerProcedure.ENCOUNTER_NOTE),any(),eq(ENCOUNTER),eq(1),eq("Synthetic summary"),eq(true));assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals(1,Collections.frequency(f.manager.events,"commit"));}
 @Test void blankFinalizeAndBranchDenialPreserveOrderAndNoMutation(){doThrow(ApiException.forbidden()).when(access).branch(BRANCH);assertEquals(403,assertThrows(ApiException.class,()->service.note(ENCOUNTER,new Note(1," "),true)).status);doNothing().when(access).branch(BRANCH);var error=assertThrows(ApiException.class,()->service.note(ENCOUNTER,new Note(1," "),true));assertEquals("Registra el resumen de la visita antes de finalizar.",error.getMessage());assertEquals(400,error.status);assertEquals(Collections.nCopies(2,SqlServerProcedure.ENCOUNTER_GET),f.calls);assertEquals("rollback",f.manager.events.getLast());}
 @Test void allEntryKindsUseSnapshotAndOnePriorGetThenOneEntry(){for(Entry input:List.of(evaluation(),observation(),annotation("GENERIC"),new Entry("ORDER",Map.of("type","Synthetic","description","Synthetic")),new Entry("PRESCRIPTION",Map.of("medication","Synthetic","dose","Synthetic","route","Synthetic","frequency","Synthetic","unit","Synthetic","quantity",1)))){var result=add(input);assertEquals(8,result.size());assertEquals(input.kind(),result.get("kind"));assertEquals(f.current.get("profileSnapshot"),result.get("profileSnapshot"));assertEquals(ENCOUNTER,result.get("encounterId"));assertEquals(SqlServerProcedure.CLINICAL_ENTRY_ADD,f.calls.getLast());assertEquals(SqlServerProcedure.ENCOUNTER_GET,f.calls.get(f.calls.size()-2));}assertEquals(5,Collections.frequency(f.manager.events,"begin:0"));assertEquals(5,Collections.frequency(f.manager.events,"commit"));verifyNoInteractions(sql);}
 @Test void observationAllowsAssistantAndDifferentProfessionalOthersRequireAuthorPro(){actor("ASI");f.current.put("professionalId",OTHER);assertEquals("OBSERVATION",add(observation()).get("kind"));verify(access).write("CORE","PRO","ASI");for(Entry p:List.of(evaluation(),annotation("GENERIC"),new Entry("ORDER",Map.of()))){int before=f.calls.size();assertEquals(403,assertThrows(ApiException.class,()->add(p)).status);assertEquals(before,f.calls.size());}actor("PRO");rejected(evaluation(),403);verify(access,never()).module("DENTAL");}
 @Test void evaluationUsesSavedSpecialtyAndEnforcesValuesRequiredNumberAndOptions(){for(Map<String,Object> payload:List.<Map<String,Object>>of(Map.of("profileCode","WRONG","values",Map.of()),Map.of("profileCode","H_FAMILY","values","bad"),Map.of("profileCode","H_FAMILY","values",Map.of()),Map.of("profileCode","H_FAMILY","values",Map.of("number"," ")),Map.of("profileCode","H_FAMILY","values",Map.of("number","not number")),Map.of("profileCode","H_FAMILY","values",Map.of("number",2,"option","C"))))rejected(new Entry("EVALUATION",payload),400);assertEquals(6,f.calls.size());assertEquals("EVALUATION",add(evaluation()).get("kind"));}
 @Test void observationRequiredFieldsAndNumericValueAreUnchanged(){for(Map<String,Object> p:List.<Map<String,Object>>of(Map.of(),Map.of("parameter","Synthetic"),Map.of("parameter","Synthetic","unit","Synthetic","value","bad"),Map.of("parameter",4,"unit","Synthetic","value",2),Map.of("parameter","x".repeat(2001),"unit","Synthetic","value",2)))rejected(new Entry("OBSERVATION",p),400);}
 @Test void annotationFamilyMappingAllComponentPatternsAndDentalModule(){for(String component:List.of("GENERIC","GENETICS","ORTHODONTIC","ENDO","PERIODONTAL","HUMAN_DENTAL"))assertEquals("ANNOTATION",add(annotation(component)).get("kind"));verify(access,times(4)).module("DENTAL");rejected(annotation("UNSUPPORTED"),400);for(String key:List.of("component","structure","condition")){var p=new LinkedHashMap<>(annotation("GENERIC").payload());p.remove(key);rejected(new Entry("ANNOTATION",p),400);}doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("DENTAL");rejected(annotation("HUMAN_DENTAL"),403);}
 @Test void orderRequiredFieldsAndPrescriptionAllFieldsQuantityAreUnchanged(){for(String key:List.of("type","description")){var p=new LinkedHashMap<String,Object>(Map.of("type","Synthetic","description","Synthetic"));p.put(key,"");rejected(new Entry("ORDER",p),400);}var valid=new LinkedHashMap<String,Object>(Map.of("medication","Synthetic","dose","Synthetic","route","Synthetic","frequency","Synthetic","unit","Synthetic","quantity",1));for(String key:List.of("medication","dose","route","frequency","unit")){var p=new LinkedHashMap<>(valid);p.remove(key);rejected(new Entry("PRESCRIPTION",p),400);}for(Object quantity:List.of(0,-1,"bad")){var p=new LinkedHashMap<>(valid);p.put("quantity",quantity);rejected(new Entry("PRESCRIPTION",p),400);}rejected(new Entry("UNKNOWN",Map.of()),400);}
 @Test void payloadLimitsDepthCyclesAndNonFiniteNeverMutate(){rejected(new Entry("OBSERVATION",Map.of("large","x".repeat(200001))),400);var deep=new LinkedHashMap<String,Object>();Map<String,Object> cursor=deep;for(int i=0;i<31;i++){var next=new LinkedHashMap<String,Object>();cursor.put("next",next);cursor=next;}rejected(new Entry("OBSERVATION",deep),400);var cycle=new LinkedHashMap<String,Object>();cycle.put("self",cycle);rejected(new Entry("OBSERVATION",cycle),400);rejected(new Entry("OBSERVATION",Map.of("value",Double.NaN)),400);rejected(new Entry("OBSERVATION",null),400);}
 @Test void permissionsContextAndMissingRequestRejectBeforeSp(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.get(ENCOUNTER)).status);actor("PRO");doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.get(ENCOUNTER)).status);for(String role:List.of("ADM","REC","PAC","RES","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,()->service.get(ENCOUNTER)).status);assertEquals(403,assertThrows(ApiException.class,()->service.start(new Start(PATIENT,BRANCH,"H_FAMILY"))).status);}actor("PRO");f.request.setAttribute("health.actor","forged");f.request.addHeader("X-Roles","PRO");assertEquals(403,assertThrows(ApiException.class,()->service.get(ENCOUNTER)).status);actor("PRO");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.get(ENCOUNTER)).status);actor("PRO");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Other","other","CLINIC","HUMAN","ACTIVE",List.of("CORE")));assertEquals(403,assertThrows(ApiException.class,()->service.note(ENCOUNTER,new Note(1,"Synthetic"),false)).status);verifyNoInteractions(f.executor,sql);}
 @Test void invalidStartAndLocalBranchErrorsHaveNoMutation(){assertEquals(400,assertThrows(ApiException.class,()->service.start(null)).status);assertEquals(400,assertThrows(ApiException.class,()->service.start(new Start(PATIENT,"bad","H_FAMILY"))).status);verify(access,never()).branch(anyString());doThrow(ApiException.missing()).when(access).branch(BRANCH);assertEquals(404,assertThrows(ApiException.class,()->service.start(new Start(PATIENT,BRANCH,"H_FAMILY"))).status);verifyNoInteractions(f.executor,sql);}
 @Test void accessWriteAndReadGuardFailBeforeQuery(){doThrow(new ApiException(403,"SUSPENDED","Safe")).when(access).write("CORE","PRO");assertEquals(403,assertThrows(ApiException.class,()->service.start(new Start(PATIENT,BRANCH,"H_FAMILY"))).status);assertEquals(403,assertThrows(ApiException.class,()->service.note(ENCOUNTER,new Note(1,"Synthetic"),false)).status);doNothing().when(access).write("CORE","PRO");doThrow(ApiException.forbidden()).when(access).roles("PRO","ASI","AUD");assertEquals(403,assertThrows(ApiException.class,()->service.note(ENCOUNTER,new Note(1,"Synthetic"),false)).status);verifyNoInteractions(f.executor,sql);}
 @Test void entryBranchBeforeAuthorAndValidationNoNewProfileLookup(){f.current.put("professionalId",OTHER);doThrow(ApiException.missing()).when(access).branch(BRANCH);assertEquals(404,assertThrows(ApiException.class,()->add(new Entry("EVALUATION",Map.of()))).status);var order=inOrder(access,f.executor);order.verify(access).write("CORE","PRO");order.verify(access).roles("PRO","ASI","AUD");order.verify(f.executor).execute(eq(SqlServerProcedure.ENCOUNTER_GET),any(),eq(ENCOUNTER));order.verify(access).branch(BRANCH);verify(access,never()).userId();assertEquals(List.of(SqlServerProcedure.ENCOUNTER_GET),f.calls);}
 @Test void malformedSnapshotErrorIsSafeAndCommitOrOuterRollbackNeverPublishAnything(){f.current.put("profileSnapshot",Map.of());var e=assertThrows(ApiException.class,()->add(evaluation()));assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertEquals(List.of(SqlServerProcedure.ENCOUNTER_GET),f.calls);f.current=encounter();f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,()->service.note(ENCOUNTER,new Note(1,"Synthetic"),false)).status);assertThrows(RuntimeException.class,()->f.manager.outer(()->{add(observation());throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));assertNull(SecurityContextHolder.getContext().getAuthentication());verifyNoInteractions(sql);}
 @Test void legacySpringConstructorAndLegacyGetRemainUsableWithoutSqlStore(){when(sql.one(anyString(),any(Object[].class))).thenAnswer(inv->encounter());when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(sql.json(any())).thenReturn("{}");when(access.tenantId()).thenReturn(TENANT);try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(ObjectMapper.class,()->f.mapper);context.registerBean(ClinicalService.class);context.refresh();var row=context.getBean(ClinicalService.class).get(ENCOUNTER);assertEquals(14,row.size());verify(sql).call(eq("sp_audit"),eq(TENANT),eq(ACTOR),eq("ENCOUNTER_READ"),eq(ENCOUNTER),eq("{}"));assertEquals(0,context.getBeanNamesForType(SqlServerClinicalStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(f.executor);}
}
